   252                  /**
   253                   * Get the first TLV record out of a byte stream
   254                   * @param[in] tlvDataBasePtr A pointer to the TLV data byte stream
   255                   * @param[in] tlvDataLen The TLV data byte stream length
   256                   * @return An instance of type TLVRecordType that contains the first TLV record. If tlvDataBasePtr is NULL or
   257                   * tlvDataLen is zero the returned TLVRecordType instance will be logically NULL, meaning TLVRecordType.isNull() will
   258                   * return true
   259                   */
   260                  TLVRecordType getFirstTLVRecord(uint8_t* tlvDataBasePtr, size_t tlvDataLen) const
   261                  {
   262                          TLVRecordType resRec(tlvDataBasePtr); // for NRVO optimization
   263
   264                          // resRec pointer is out-bounds of the TLV records memory
   265                          if (resRec.getRecordBasePtr() + resRec.getTotalSize() > tlvDataBasePtr + tlvDataLen)
   266                                  resRec.assign(NULL);
   267
   268                          // check if there are records at all and the total size is not zero
   269                          if (!resRec.isNull() && (tlvDataLen == 0 || resRec.getTotalSize() == 0))
   270                                  resRec.assign(NULL);
   271
   272                          return resRec;
   273                  }
