   275                  /**
   276                   * Get a TLV record that follows a given TLV record in a byte stream
   277                   * @param[in] record A given TLV record
   278                   * @param[in] tlvDataBasePtr A pointer to the TLV data byte stream
   279                   * @param[in] tlvDataLen The TLV data byte stream length
   280                   * @return An instance of type TLVRecordType that wraps the record following the record given as input. If the
   281                   * input record.isNull() is true or if the next record is out of bounds of the byte stream, a logical NULL instance
   282                   * of TLVRecordType will be returned, meaning TLVRecordType.isNull() will return true
   283                   */
   284                  TLVRecordType getNextTLVRecord(TLVRecordType& record, const uint8_t* tlvDataBasePtr, size_t tlvDataLen) const
   285                  {
   286                          TLVRecordType resRec(NULL); // for NRVO optimization
   287
   288                          if (record.isNull())
   289                                  return resRec;
   290
   291                          resRec.assign(record.getRecordBasePtr() + record.getTotalSize());
   292                          if (resRec.getTotalSize() == 0)
   293                                  resRec.assign(NULL);
   294
   295                          // resRec pointer is out-bounds of the TLV records memory
   296                          if ((resRec.getRecordBasePtr() - tlvDataBasePtr) < 0)
   297                                  resRec.assign(NULL);
   298
   299                          // resRec pointer is out-bounds of the TLV records memory
   300                          if (!resRec.isNull() && resRec.getRecordBasePtr() + resRec.getTotalSize() > tlvDataBasePtr + tlvDataLen)
   301                                  resRec.assign(NULL);
   302
   303                          return resRec;
   304                  }
