   306                  /**
   307                   * Search for the first TLV record that corresponds to a given record type (the 'T' in __Type__-Length-Value)
   308                   * @param[in] recordType The record type to search for
   309                   * @param[in] tlvDataBasePtr A pointer to the TLV data byte stream
   310                   * @param[in] tlvDataLen The TLV data byte stream length
   311                   * @return An instance of type TLVRecordType that contains the result record. If record was not found a logical
   312                   * NULL instance of TLVRecordType will be returned, meaning TLVRecordType.isNull() will return true
   313                   */
   314                  TLVRecordType getTLVRecord(uint32_t recordType, uint8_t* tlvDataBasePtr, size_t tlvDataLen) const
   315                  {
   316                          TLVRecordType curRec = getFirstTLVRecord(tlvDataBasePtr, tlvDataLen);
   317                          while (!curRec.isNull())
   318                          {
   319                                  if (curRec.getType() == recordType)
   320                                  {
   321                                          return curRec;
   322                                  }
   323
   324                                  curRec = getNextTLVRecord(curRec, tlvDataBasePtr, tlvDataLen);
   325                          }
   326
   327                          curRec.assign(NULL);
   328                          return curRec; // for NRVO optimization
   329                  }
