   331                  /**
   332                   * Get the TLV record count in a given TLV data byte stream. For efficiency purposes the count is being cached
   333                   * so only the first call to this method will go over all the TLV records, while all consequent calls will return
   334                   * the cached number. This implies that if there is a change in the number of records, it's the user's responsibility
   335                   * to call changeTLVRecordCount() with the record count change
   336                   * @param[in] tlvDataBasePtr A pointer to the TLV data byte stream
   337                   * @param[in] tlvDataLen The TLV data byte stream length
   338                   * @return The TLV record count
   339                   */
   340                  size_t getTLVRecordCount(uint8_t* tlvDataBasePtr, size_t tlvDataLen) const
   341                  {
   342                          if (m_RecordCount != (size_t)-1)
   343                                  return m_RecordCount;
   344
   345                          m_RecordCount = 0;
   346                          TLVRecordType curRec = getFirstTLVRecord(tlvDataBasePtr, tlvDataLen);
   347                          while (!curRec.isNull())
   348                          {
   349                                  m_RecordCount++;
   350                                  curRec = getNextTLVRecord(curRec, tlvDataBasePtr, tlvDataLen);
   351                          }
   352
   353                          return m_RecordCount;
   354                  }
   355
   356                  /**
   357                   * As described in getTLVRecordCount(), the TLV record count is being cached for efficiency purposes. So if the
   358                   * number of TLV records change, it's the user's responsibility to call this method with the number of TLV records
   359                   * being added or removed. If records were added the change should be a positive number, or a negative number
   360                   * if records were removed
   361                   * @param[in] changedBy Number of records that were added or removed
   362                   */
   363                  void changeTLVRecordCount(int changedBy) { if (m_RecordCount != (size_t)-1) m_RecordCount += changedBy; }
   364          };
